import type { TroubleCodeGuide } from "./trouble-code-data";

const sx={label:"Honda ServiceExpress",url:"https://techinfo.honda.com/",note:"Honda VIN-specific DTC flowcharts, wiring diagrams, service bulletins and campaign status"};
const manuals={label:"Honda Owners — Pilot manuals",url:"https://mygarage.honda.com/s/manuals-search",note:"Official model-year operating, warning and maintenance information"};
const rings={label:"Honda Service Bulletin 13-082 — 2009–2013 Pilot P0301–P0304",url:"https://static.nhtsa.gov/odi/tsbs/2022/MC-10216874-0001.pdf",note:"Warranty-extension diagnostic/repair sequence for specified spark-plug fouling and piston-ring cases; VIN/status and procedure requirements apply"};
const coldOil={label:"Honda Service Bulletin 13-055 — selected 2013 Pilot cold-start misfire/VCM codes",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10052924-4799.pdf",note:"Narrow VIN ranges; below 30°F ECT and rocker-arm oil pressure above 92 psi branch with relief-valve spring repair"};
const injectors={label:"Honda V6 fuel-injector warranty-extension notice",url:"https://static.nhtsa.gov/odi/tsbs/2021/MC-10187289-0001.pdf",note:"Certain 2016–2019 Pilot vehicles; P0420/P0430 with P0300–P0306/P219A/P219B branches, VIN inquiry required"};
const oldEvap={label:"Honda Service Bulletin 99-075 — 2003–2004 Pilot P1456/P1457",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10053545-3978.pdf",note:"Procedure A provides Honda FTP, valve and leak testing for the listed early Pilot EVAP system"};
const capEvap={label:"Honda Service Bulletin 14-010 — 2012–2013 Pilot P0455/P0456",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10129552-9999.pdf",note:"Cap-gasket friction branch for all 2012 Pilot and listed early 2013 VIN ranges"};
const filler2016={label:"Honda Tech Line ATS 170206 — 2016 Pilot capless filler leak",url:"https://static.nhtsa.gov/odi/tsbs/2017/MC-10127365-9999.pdf",note:"For a verified filler-neck P0455/P0456 leak, replace serviceable mis-fuel inhibit/main-flap components rather than the entire fill pipe"};

const vehicle={name:"Honda Pilot",kicker:"HONDA PILOT · J35 V6, VCM AND EMISSIONS DIAGNOSTICS",breadcrumb:"Honda Pilot",about:"Honda Pilot engine and emissions diagnostics",yearsIntro:"Pilot diagnostics span several J35 V6 generations, cable and electronic throttle systems, port and direct injection, VCM cylinder-deactivation hardware, conventional caps and later capless fillers, plus FWD/AWD drivetrains. The V6 has two cylinder banks and six cylinder-specific misfire codes. Confirm VIN, model year, engine/calibration, emissions label, drivetrain and current Honda bulletin or warranty-extension eligibility before testing or ordering parts."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`honda/pilot/${x.slug}`,vehicle});

export const troubleCodePilot:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Honda Pilot: Bank 1 Catalyst, Injector and Misfire Diagnosis",description:"Diagnose Pilot P0420 by identifying Bank 1, testing misfire, injector balance, fuel control, exhaust leaks and sensor response before catalyst replacement.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady MIL with normal power generally permits a short diagnostic trip. Stop for a flashing lamp, strong fuel odor, severe shaking, converter rattle or major power loss because active misfire can overheat the catalyst and broken substrate can restrict exhaust.",quickAnswer:"P0420 means the PCM judged Bank 1 catalyst oxygen-storage performance below threshold; it does not identify the catalyst as the original failure. Save P0430, P0300–P0306 and P219A/P219B companions, fuel correction, injector data and readiness. Identify Bank 1 using the exact J35 service diagram—do not use a generic front/rear rule. Certain 2016–2019 Pilots were included in Honda fuel-injector warranty-extension bulletins where injector wear/clogging and software interpretation could produce catalyst and misfire/air-fuel codes. VIN eligibility and the specific code combination matter; other years require normal exhaust, sensor, fuel and mechanical diagnosis.",symptoms:[{key:"normal",label:"MIL on, Pilot feels normal",response:"Preserve readiness and complete prerequisites before clearing."},{key:"misfire",label:"P030x/P219A also stored",response:"Test cylinder/injector balance and check exact program eligibility first."},{key:"flash",label:"MIL flashes under load",response:"Stop sustained driving and repair active misfire."},{key:"rattle",label:"Rattle or loss of power",response:"Inspect shields and test substrate restriction."}],causes:[{cause:"Bank 1 catalyst deterioration",evidence:"Prerequisites pass and Honda evaluation fails",firstTest:"Bank-specific catalyst test"},{cause:"Injector imbalance in covered 2016–2019 population",evidence:"Matched VIN/status and companion codes",firstTest:"Honda program diagnostic sequence"},{cause:"Misfire/rich operation overheated catalyst",evidence:"P030x history, negative correction or fouled plugs",firstTest:"Repair combustion fault"},{cause:"Oil/coolant contamination or VCM oil use",evidence:"Consumption, deposits or coolant loss",firstTest:"Mechanical/cooling diagnosis"},{cause:"Bank 1 exhaust leak or sensor fault",evidence:"Soot/tick or failed response/electrical test",firstTest:"Leak then sensor test"}],freezeFrame:["P0420/P0430 and P0300–P0306/P219A/P219B","Bank 1/2 fuel correction","Cylinder misfire counts","A/F and downstream O2 data by bank","Injector balance/fuel pressure","VIN, campaign status and repair history"],steps:[{title:"Preserve every companion code",detail:"The injector-program branch depends on code context, not P0420 alone."},{title:"Identify Bank 1 and its converter",detail:"Use the exact J35 diagram before testing sensors or exhaust."},{title:"Correct catalyst killers",detail:"Resolve misfire, injector imbalance, oil/coolant entry and rich operation."},{title:"Inspect Bank 1 exhaust cold",detail:"Check flanges and bungs for soot or leakage."},{title:"Evaluate sensors and catalyst",detail:"Compare banks under Honda enable conditions."},{title:"Verify VIN-specific program",detail:"Use Honda VIN inquiry; do not promise expired or inapplicable coverage."},{title:"Complete monitor",detail:"Confirm no pending P0420 after repair."}],dontReplace:"Do not replace Bank 1 catalyst or rear sensor from the code alone. A weak injector can damage the new converter, and the warranty-extension notice does not cover every Pilot or every isolated P0420.",yearNotes:["Certain 2016–2019 Pilots appear in Honda's V6 injector warranty-extension communications; VIN inquiry controls eligibility.","P0420 is Bank 1 and P0430 is Bank 2; correct bank identification is essential.","2009–2013 VCM oil-consumption/misfire history can be relevant upstream evidence.","Direct-injection fuel systems require specified depressurization and measurement."],faqs:[{question:"Does P0420 prove the catalyst failed?",answer:"No. Injector, misfire, mixture, contamination, leak and sensor causes come first."},{question:"Which side is Bank 1?",answer:"Use the exact J35 model-year service diagram, not a generic rule."},{question:"Can I drive?",answer:"Usually briefly with a steady lamp; stop for flashing, odor, rattle or power loss."},{question:"Does the injector extension cover every Pilot?",answer:"No. VIN, year and diagnostic conditions determine eligibility."},{question:"Will a rear O2 sensor fix it?",answer:"Only if circuit/response testing proves it faulty."},{question:"Can oil use damage a catalyst?",answer:"Yes, ash can reduce catalyst activity."},{question:"Why compare banks?",answer:"The unaffected bank provides a useful same-engine reference."},{question:"What confirms repair?",answer:"Healthy prerequisites and a completed monitor without pending P0420."}],deepDive:[{heading:"The second bank is a built-in comparison",paragraphs:["Compare correction and sensor behavior under the same load, temperature and fuel.","A major bank split can localize injector, intake, exhaust or mechanical causes before catalyst replacement."]},{heading:"The injector program is conditional",paragraphs:["Honda linked certain P0420/P0430 and misfire/air-fuel cases to injector manufacturing and software interpretation.","A matching keyword does not establish VIN eligibility or the required remedy."]},{heading:"A catalyst can be the victim",paragraphs:["Misfire, oil burning and injector imbalance can overheat or contaminate substrate.","Review permanent codes and consumption history even when the engine is smooth today."]}],sources:[injectors,sx,manuals]}),

article({slug:"p0171",code:"P0171",title:"P0171 Code Honda Pilot: Bank 1 Lean Diagnosis Using Bank Comparison",description:"Diagnose Pilot P0171 by comparing V6 banks at idle and load, smoke-testing intake/purge paths and measuring fuel pressure and injector balance.",definition:"Fuel System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid towing and hard acceleration if the Pilot hesitates, stalls or carries large positive correction. Stop for flashing misfire, detonation, severe power loss or fuel-pressure warnings. A smooth vehicle with a steady lamp may make a short controlled diagnostic trip.",quickAnswer:"P0171 means the PCM added fuel beyond its limit on Bank 1. The most useful Pilot clue is Bank 2: if only Bank 1 is lean, inspect its manifold sealing, exhaust ahead of the A/F sensor and injector contribution. If P0171 and P0174 rise similarly, prioritize shared intake, purge, load sensing and fuel supply. Compare correction at hot idle, raised rpm and load. On direct-injected Pilots, evaluate low and high fuel pressure safely. Do not replace Bank 1 A/F sensor until mixture, leakage, wiring and controlled response prove bias.",symptoms:[{key:"one",label:"Only Bank 1 correction high",response:"Localize Bank 1 intake, exhaust and injector contribution."},{key:"both",label:"P0171 and P0174 together",response:"Test shared air/load/fuel and purge causes."},{key:"idle",label:"Worst at idle",response:"Smoke-test manifold, PCV and brake-booster paths."},{key:"load",label:"Worse towing/accelerating",response:"Graph fuel pressure and injector/load data."}],causes:[{cause:"Bank 1 intake-gasket or local vacuum leak",evidence:"Bank split, strongest at idle",firstTest:"Regulated smoke test"},{cause:"Shared PCV/booster/purge leak",evidence:"Both banks positive, idle dominant",firstTest:"Smoke and purge sealing"},{cause:"Fuel-pressure/volume shortage",evidence:"Both banks worsen under load",firstTest:"Low/high-side pressure test"},{cause:"Bank 1 injector restriction",evidence:"Bank/cylinder contribution imbalance",firstTest:"Injector balance/contribution"},{cause:"Bank 1 exhaust leak or A/F bias",evidence:"Cold soot/tick or failed response",firstTest:"Leak inspection then circuit test"}],freezeFrame:["Bank 1 and Bank 2 STFT/LTFT","RPM, load, ECT and speed","MAP/MAF and throttle data","Low/high fuel pressures","Cylinder contribution/misfire","Recent intake, injector or purge work"],steps:[{title:"Save both banks",detail:"Clearing removes the comparison that makes V6 diagnosis efficient."},{title:"Compare idle, raised rpm and load",detail:"Direction of change distinguishes vacuum leakage from fuel shortage."},{title:"Smoke-test shared and bank paths",detail:"Include PCV, booster, purge and manifold sealing."},{title:"Measure fuel delivery",detail:"Do not infer pressure from sound or idle alone."},{title:"Test Bank 1 injector/exhaust",detail:"Use balance and cold leak inspection when only one bank differs."},{title:"Verify both banks",detail:"Repeat original conditions with balanced correction and no pending code."}],dontReplace:"Do not replace the Bank 1 A/F sensor because the PCM says lean. It can be correctly reporting extra air or insufficient fuel. Never loosen a direct-injection line to check for pressure.",yearNotes:["Early port-injected and later direct-injected J35 engines require different fuel tests.","Bank 2 is a valuable control when only P0171 is present.","P0171 plus P0174 points toward a shared cause more than two simultaneous sensors.","VCM operation can change active-cylinder and trim context; compare under stable conditions."],faqs:[{question:"Does P0171 mean Bank 1 sensor failed?",answer:"No. It means correction reached a lean limit."},{question:"What if P0174 is also stored?",answer:"Prioritize shared intake/load/fuel causes."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when correction is highest at idle."},{question:"Can low fuel pressure affect one bank?",answer:"Usually both, though injector/rail details can create imbalance."},{question:"Can I drive?",answer:"Limit load if it hesitates; stop for flashing MIL or severe power loss."},{question:"Why compare banks?",answer:"They share many conditions, so differences localize the fault."},{question:"Can an exhaust leak cause lean data?",answer:"Yes if it admits oxygen ahead of Bank 1 feedback."},{question:"What confirms repair?",answer:"Balanced correction at idle/load and no pending P0171."}],deepDive:[{heading:"A V6 offers its own control sample",paragraphs:["Both banks breathe shared filtered air and fuel under the same ambient conditions.","A bank split makes two identical sensor failures less plausible than a localized leak or injector issue."]},{heading:"Idle-versus-load is diagnostic",paragraphs:["Vacuum leakage is proportionally largest at idle; weak fuel delivery becomes obvious under demand.","Graph rather than relying on one freeze-frame percentage."]},{heading:"Direct injection adds a high-pressure side",paragraphs:["Later Pilots can meet low-side pressure while the high-pressure pump/rail misses command.","Use protected, scan-based and Honda-specified tests; never crack a live line."]}],sources:[sx,manuals]}),

article({slug:"p0300",code:"P0300",title:"P0300 Code Honda Pilot: V6 Misfire, VCM and Injector Diagnosis",description:"Diagnose Pilot P0300 with six-cylinder counters, bank patterns, plugs, injectors and compression, including exact 2009–2013 and 2016–2019 Honda branches.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing MIL means active catalyst-damaging misfire; stop as soon as safe. Do not tow or accelerate hard. Stop also for severe shaking, raw fuel, overheating, low oil pressure or mechanical noise.",quickAnswer:"P0300 means multiple or non-dominant cylinder-speed disturbances. Preserve P0301–P0306, bank imbalance codes, counters and freeze data. Honda history creates two separate Pilot branches: bulletin 13-082 covers defined 2009–2013 P0301–P0304 plug-fouling/piston-ring cases, while later injector warranty bulletins cover certain 2016–2019 vehicles with catalyst plus misfire/air-fuel code combinations. A narrow 13-055 branch applies to specified 2013 VINs below 30°F with rocker-arm oil pressure above 92 psi. None authorizes blind ring, injector or relief-spring replacement from P0300 alone.",symptoms:[{key:"flash",label:"MIL flashes",response:"Stop load and protect both catalysts."},{key:"oil",label:"2009–2013 with oil-fouled plugs",response:"Check VIN/status and follow 13-082 diagnosis."},{key:"cold",label:"Selected 2013, very cold start",response:"Check 13-055 VIN, ECT and rocker-pressure thresholds."},{key:"later",label:"2016–2019 with P0420/P0430/P219A/B",response:"Check injector-program eligibility."}],causes:[{cause:"Plug/coil/boot faults",evidence:"Cylinder leader and controlled swap follows",firstTest:"Labelled plug/coil test"},{cause:"Injector imbalance or pressure fault",evidence:"Contribution/pressure error and later bulletin context",firstTest:"Injector/fuel tests and VIN check"},{cause:"Oil-fouling/ring issue in 13-082 population",evidence:"Matched 2009–2013 vehicle, codes and plug findings",firstTest:"Bulletin sequence"},{cause:"Cold high-oil-pressure VCM event",evidence:"Exact 2013 VIN, ECT below 30°F, pressure above 92 psi",firstTest:"13-055 workflow"},{cause:"Compression, valve/timing or shared air/fuel fault",evidence:"Counts pattern and mechanical/trim evidence",firstTest:"Compression, bank and system tests"}],freezeFrame:["P0301–P0306 and P219A/B","All six cylinder counters","Bank 1/2 correction","ECT and rocker-arm oil pressure","Plug deposits in cylinder order","VIN/program and prior repair history"],steps:[{title:"Preserve six-cylinder pattern",detail:"Cylinder and bank grouping controls the next test."},{title:"Inspect plugs in exact order",detail:"Oil, fuel, coolant and gap evidence must remain cylinder-specific."},{title:"Use targeted coil tests",detail:"Move one suspected coil and observe whether the count follows."},{title:"Test injectors and pressure",detail:"Compare contribution and both fuel sides where applicable."},{title:"Apply only matched Honda branch",detail:"Check every VIN, temperature, pressure, code and prior-repair condition."},{title:"Prove mechanical health",detail:"Compression/leak-down follows faults that stay on the cylinder."},{title:"Verify cold and load",detail:"Do not provoke a flashing-MIL road test."}],dontReplace:"Do not replace six coils, piston rings, injectors or an oil-pump relief spring from P0300 alone. Each Honda program has exact application and diagnostic gates, and current warranty status must be checked by VIN.",yearNotes:["13-082 concerns specified 2009–2013 P0301–P0304 plug-fouling/ring cases.","13-055 is limited to narrow 2013 VIN ranges with ECT below 30°F and rocker pressure above 92 psi.","Certain 2016–2019 Pilots appear in V6 injector warranty communications.","P0305/P0306 are not the same 13-082 ring branch as P0301–P0304."],faqs:[{question:"Does P0300 mean all six coils are bad?",answer:"No. It names no failed component."},{question:"Can I drive?",answer:"Not with a flashing lamp or severe shaking."},{question:"Does every 2009–2013 Pilot need rings?",answer:"No. Codes, plug findings, software/return sequence and eligibility matter."},{question:"Does every 2013 cold misfire need a spring?",answer:"No. VIN, ECT and pressure thresholds are explicit."},{question:"Can injectors cause it?",answer:"Yes, especially with imbalance/catalyst companion codes."},{question:"Why label plugs?",answer:"Cylinder deposits decide which bulletin or mechanical path is plausible."},{question:"Can VCM affect the pattern?",answer:"Yes; active-cylinder/oil-control context must be recorded."},{question:"What confirms repair?",answer:"Stable counters through original cold/load conditions."}],deepDive:[{heading:"Bulletin overlap is not interchangeability",paragraphs:["The ring, relief-spring and injector branches describe different vehicle populations and evidence.","A search result showing P0300 does not make their remedies interchangeable."]},{heading:"Bank and cylinder pattern tells a story",paragraphs:["One cylinder suggests targeted ignition/fuel/mechanical tests; one bank suggests local air/fuel/timing causes.","All cylinders together raise shared fuel, voltage and contaminated-fuel possibilities."]},{heading:"A plug can determine the branch",paragraphs:["Bulletin 13-082 requires plug-fouling inspection within its sequence.","Replacing plugs before recording them may erase the very evidence needed for diagnosis."]}],sources:[rings,coldOil,injectors,sx]}),

article({slug:"p2646",code:"P2646",title:"P2646 Code Honda Pilot: Verify the DTC Before Applying VTEC Advice",description:"Diagnose a Pilot scanner report of P2646 by confirming the raw code and J35 definition, then testing oil, wiring and VCM hardware rather than using CR-V advice.",definition:"Rocker Arm Oil Pressure Switch Circuit Low Voltage (generic scanner wording; verify Honda J35 definition)",severity:"Diagnose promptly",driveAdvice:"Keep load low until the code is verified. Stop immediately for a red oil-pressure warning, knock or severe valvetrain noise. A generic scanner label is not a reason to exercise VCM/VTEC at high rpm.",quickAnswer:"The Pilot uses a J35 V6 with VCM oil-control hardware and commonly documented rocker-arm pressure codes such as P3400/P3497, not the K24 four-cylinder repair path often associated with P2646. First record the complete raw DTC—including suffix/status—and confirm that the PCM, VIN and scan tool are correctly identified using Honda ServiceExpress/HDS. If P2646 is truly reported, follow the exact J35 circuit definition and schematic. Check oil level/grade, battery voltage, connector integrity, commanded valve state and actual pressure. Do not apply bulletin 13-021: it lists Accord four-cylinder, Civic, 2002–2009 CR-V and other models, but no Pilot.",symptoms:[{key:"generic",label:"Generic scanner alone shows P2646",response:"Confirm with Honda-capable scan data before parts."},{key:"other",label:"P3400/P3497 also present",response:"Use Pilot VCM bank-specific diagnostics."},{key:"oil",label:"Oil lamp/noise",response:"Shut down and verify lubrication pressure."},{key:"cold",label:"Selected 2013 cold-start misfire codes",response:"Check 13-055 rather than a CR-V switch bulletin."}],causes:[{cause:"Scan-tool definition/vehicle-profile mismatch",evidence:"Honda-capable tool reports different raw DTC/definition",firstTest:"Full DTC and VIN/module verification"},{cause:"Low/wrong/degraded oil",evidence:"Level/specification/history abnormal",firstTest:"Correct and investigate cause"},{cause:"J35 rocker/VCM circuit fault",evidence:"Model-specific state/voltage test fails",firstTest:"Exact schematic and loaded test"},{cause:"Oil-control valve/pressure problem",evidence:"Command differs from measured state",firstTest:"Honda actuation/pressure procedure"},{cause:"Cold-pressure condition in narrow 2013 branch",evidence:"13-055 VIN/ECT/pressure/code gates match",firstTest:"Bulletin-specific diagnosis"}],freezeFrame:["Exact raw code and status","VIN/module/scan profile","P3400/P3497 and misfire companions","Oil level/grade/history","VCM command and bank pressure states","ECT, rpm, load and battery voltage"],steps:[{title:"Verify code identity",detail:"Use HDS-equivalent data and record suffix/status before interpreting generic text."},{title:"Reject the CR-V bulletin",detail:"13-021 does not list Pilot."},{title:"Protect lubrication",detail:"Stop for oil warning/noise and check level/specification."},{title:"Identify VCM bank/circuit",detail:"Use exact J35 year wiring and component location."},{title:"Test command, circuit and pressure",detail:"Separate electrical state from hydraulic response."},{title:"Verify without forced operation",detail:"Confirm no pending code under safe enable conditions."}],dontReplace:"Do not install a CR-V/Accord rocker-arm pressure switch or cite 13-021 for a Pilot. Verify the raw DTC first; generic scan translations and wrong vehicle profiles can send diagnosis to the wrong engine family.",yearNotes:["Pilot is J35 V6, whereas 13-021's CR-V coverage is K-series 2002–2009.","Pilot VCM commonly uses P3400/P3497 bank-specific monitoring.","13-055 concerns narrow 2013 cold-start misfire/P3400/P3497 cases, not a universal P2646 repair.","Oil warning/noise takes priority over any code-label dispute."],faqs:[{question:"Does 13-021 cover Honda Pilot?",answer:"No. Pilot is not in its affected-vehicle table."},{question:"Why might my scanner say P2646?",answer:"Generic definitions or vehicle/module identification may differ; confirm the raw code."},{question:"Is P3400 the same code?",answer:"No. It is a bank-specific VCM rocker-arm oil-pressure code."},{question:"Can I drive?",answer:"Limit load; stop for oil warning or mechanical noise."},{question:"Should I replace a pressure switch?",answer:"Only after the exact J35 circuit and failure are verified."},{question:"Can oil condition matter?",answer:"Yes, VCM operation is hydraulic."},{question:"What tool should verify it?",answer:"Honda HDS or a scan tool with accurate Honda enhanced data."},{question:"What confirms repair?",answer:"Correct model-specific command/feedback and no pending raw DTC."}],deepDive:[{heading:"A valid code needs a valid definition",paragraphs:["The five-character number must be tied to the correct module, calibration and manufacturer service information.","A plausible generic phrase is not enough to order a K-series component for a J35."]},{heading:"VCM is bank-aware",paragraphs:["The Pilot deactivates cylinders through bank-specific rocker-arm oil circuits.","P3400/P3497 and companion data often provide more relevant direction than generic VTEC articles."]},{heading:"Oil safety comes before semantics",paragraphs:["If the red pressure lamp or mechanical noise occurs, shut down even while code identity is unresolved.","Electrical troubleshooting is inappropriate until basic lubrication risk is excluded."]}],sources:[coldOil,sx,manuals]}),

article({slug:"p2647",code:"P2647",title:"P2647 Code Honda Pilot: Confirm J35 Rocker-Arm Code and High State",description:"Handle a Pilot P2647 report by confirming Honda's raw DTC/definition, then testing the correct J35 VCM bank, circuit and oil pressure.",definition:"Rocker Arm Oil Pressure Switch Circuit High Voltage (generic scanner wording; verify Honda J35 definition)",severity:"Diagnose promptly",driveAdvice:"Avoid towing and high load until code identity and oil-control operation are verified. Stop for the oil-pressure lamp, knock or loud valvetrain noise. Do not repeatedly command cylinder deactivation as a roadside test.",quickAnswer:"A generic P2647 description points to a high rocker-arm pressure-switch circuit state, but Pilot J35 service information normally organizes VCM oil-pressure faults by bank with codes such as P3400/P3497. Confirm the exact raw DTC, module and VIN with Honda-capable data before borrowing a four-cylinder repair. Bulletin 13-021 does not include Pilot. If Honda data confirms an applicable high-state circuit fault, graph VCM command and switch feedback, load-test the signal circuit, check oil condition, and determine whether hydraulic pressure fails to release. Open wiring and trapped pressure can look identical to the PCM.",symptoms:[{key:"generic",label:"Only a generic scanner reports it",response:"Verify raw code/module with Honda enhanced data."},{key:"bank",label:"P3400 or P3497 stored",response:"Follow the identified VCM bank's Pilot procedure."},{key:"oil",label:"Oil warning/noise",response:"Stop and test lubrication immediately."},{key:"hot",label:"Appears after heat/load",response:"Graph command/state and inspect heat-sensitive wiring/oil response."}],causes:[{cause:"Incorrect generic definition/profile",evidence:"Honda tool identifies another code or bank",firstTest:"VIN/module/raw-code verification"},{cause:"Open/high-resistance signal circuit",evidence:"High state persists and loaded test fails",firstTest:"Terminal/voltage-drop test"},{cause:"VCM oil-control valve does not release",evidence:"Command off but pressure state stays active",firstTest:"Bank-specific actuation/pressure test"},{cause:"Oil passage/condition problem",evidence:"Delayed hydraulic response or contamination",firstTest:"Oil and passage inspection"},{cause:"Switch fault in verified J35 circuit",evidence:"Circuit/hydraulics pass and switch test fails",firstTest:"Exact component test"}],freezeFrame:["Raw DTC/module/status","P3400/P3497 companions","VCM command and bank feedback","Oil level/grade/history","ECT, rpm, load and voltage","Scan-tool vehicle profile"],steps:[{title:"Confirm raw information",detail:"Do not diagnose from a generic English label alone."},{title:"Use the J35 schematic",detail:"Identify bank, valve and switch for the exact year."},{title:"Reject 13-021 applicability",detail:"Its affected list does not contain Pilot."},{title:"Graph command versus feedback",detail:"Determine constant versus delayed high state."},{title:"Load-test wiring and hydraulic release",detail:"Separate open circuit from trapped pressure."},{title:"Verify both transitions",detail:"Confirm no pending model-specific DTC."}],dontReplace:"Do not treat a Pilot like a 2002–2009 CR-V and do not order a pressure switch until the raw code and J35 circuit are verified. High state can be caused by wiring or hydraulic release, not only the switch.",yearNotes:["Pilot is absent from Honda bulletin 13-021.","J35 VCM diagnostics are bank-specific and frequently use P3400/P3497.","A high-state generic description can represent an open circuit or retained pressure.","VIN/model-year Honda data controls the actual component and threshold."],faqs:[{question:"Does 13-021 apply?",answer:"No; Pilot is not listed."},{question:"How is high state different from low?",answer:"It changes likely circuit and hydraulic failure directions."},{question:"Can a scan tool be wrong?",answer:"It may use a generic definition or wrong profile; confirm with Honda data."},{question:"Can I drive?",answer:"Limit load; stop for an oil warning or noise."},{question:"Is the switch always faulty?",answer:"No. Wiring and trapped hydraulic pressure can mimic it."},{question:"Why check P3400/P3497?",answer:"They are the Pilot's common bank-specific VCM pressure codes."},{question:"Can dirty oil matter?",answer:"Yes, it can delay oil-control response."},{question:"What confirms repair?",answer:"Correct bank command/feedback and no pending DTC."}],deepDive:[{heading:"High state has electrical and hydraulic meanings",paragraphs:["An open signal may be interpreted high; a healthy switch may remain high if oil does not release.","Only command-versus-feedback and circuit/pressure testing separates them."]},{heading:"Vehicle identification is diagnostic",paragraphs:["A scanner loaded with the wrong profile can attach a valid generic phrase to an irrelevant repair path.","Record VIN, PCM identity, calibration and full DTC before touching hardware."]},{heading:"VCM is not four-cylinder VTEC",paragraphs:["The underlying use of oil-operated rocker hardware is related, but bank layout, commands and fault logic differ.","Use Pilot J35 service information rather than a search result for another Honda."]}],sources:[coldOil,sx,manuals]}),

article({slug:"p1457",code:"P1457",title:"P1457 Code Honda Pilot: 2003–2004 Canister-Side EVAP Diagnosis",description:"Diagnose early Pilot P1457 with Honda Procedure A, FTP data, valve-isolation and safe leak testing instead of assuming a gas cap.",definition:"EVAP Control System Leakage (EVAP Canister System)",severity:"Service soon",driveAdvice:"Brief driving is normally acceptable with no fuel odor or wetness. Park outdoors and stop for liquid fuel, strong vapor smell, damaged tank plumbing or refueling problems. Keep ignition sources away and use only regulated EVAP equipment.",quickAnswer:"On 2003–2004 Pilot, P1457 points to the canister side of Honda's older EVAP system, while P1456 points toward the fuel-tank side. Honda bulletin 99-075 Procedure A includes those two Pilot model years and lays out FTP-sensor, HDS function, valve and vacuum tests. A loose cap is therefore not the automatic P1457 conclusion. Preserve fuel level/soak conditions, test purge and canister-side valve sealing, inspect hoses and isolate the system. Later Pilots use generic P044x strategies and should not inherit the early component map.",symptoms:[{key:"early",label:"2003–2004 Pilot",response:"Use 99-075 Procedure A and its FTP thresholds."},{key:"odor",label:"Strong fuel odor",response:"Stop and check for liquid leakage safely."},{key:"cap",label:"New cap did not help",response:"Focus on canister-side routing and valves."},{key:"return",label:"Intermittent comeback",response:"Run HDS EVAP function test before disturbing evidence."}],causes:[{cause:"Canister-side hose leak/misrouting",evidence:"Visual or sectional smoke/vacuum result",firstTest:"Routing inspection and safe smoke"},{cause:"Vent/bypass valve leakage or restriction",evidence:"Fails command/vacuum hold",firstTest:"Individual valve test"},{cause:"Purge valve does not seal",evidence:"Manifold vacuum passes while commanded closed",firstTest:"Closed-state sealing"},{cause:"Canister/two-way valve fault",evidence:"Other sections pass",firstTest:"Procedure A isolation"},{cause:"FTP sensor/circuit bias",evidence:"Atmospheric or commanded values implausible",firstTest:"Signal/reference comparison"}],freezeFrame:["Fuel level and soak temperature","P1456 and electrical companions","FTP sensor value","Purge/vent commands and sealing","Recent tank/canister work","Hose routing and corrosion/water evidence"],steps:[{title:"Confirm 2003–2004 applicability",detail:"Later Pilot layouts use different codes and components."},{title:"Run Honda EVAP function test",detail:"Record pass/fail and FTP behavior before disassembly."},{title:"Separate tank and canister sides",detail:"P1457 is the canister-side direction."},{title:"Test valves mechanically",detail:"Clicking does not prove sealing or flow."},{title:"Section with regulated equipment",detail:"Follow Procedure A; never use unregulated air."},{title:"Verify monitor completion",detail:"Confirm repair under proper fuel/soak conditions."}],dontReplace:"Do not call P1457 a guaranteed gas-cap fault or replace the canister before isolating valves and hoses. Bulletin 99-075 applies to 2003–2004 Pilot, not every year.",yearNotes:["99-075 lists 2003–2004 Pilot under Procedure A.","P1457 is canister-side; P1456 is fuel-tank-side on that strategy.","Later Pilot P044x systems and capless fillers use different diagnostics.","FTP plausibility matters before interpreting vacuum results."],faqs:[{question:"Is P1457 a gas-cap code?",answer:"Not primarily; it identifies the canister side."},{question:"Which Pilot years are in 99-075?",answer:"2003–2004."},{question:"Can I drive?",answer:"Usually briefly without odor or wet fuel."},{question:"What is P1456?",answer:"The older Honda fuel-tank-side leak code."},{question:"Does a click prove a valve?",answer:"No. It must seal and flow correctly."},{question:"Can smoke testing help?",answer:"Yes, with EVAP-safe pressure and correct sectioning."},{question:"Does this apply to 2016 Pilot?",answer:"No; that vehicle uses a different EVAP/filler system."},{question:"What confirms repair?",answer:"Correct FTP/valve behavior and a completed monitor."}],deepDive:[{heading:"Honda divided the older system",paragraphs:["P1456 and P1457 point to different diagnostic regions.","That division is more useful than a generic small/large-leak label."]},{heading:"The HDS function test preserves direction",paragraphs:["A current pass may reveal an intermittent condition rather than a permanent opening.","Record results before tightening, disconnecting or replacing anything."]},{heading:"A valve can fail without an electrical code",paragraphs:["A solenoid may receive command and click while its seat leaks or passage is restricted.","Vacuum hold and flow are separate from coil continuity."]}],sources:[oldEvap,sx,manuals]}),

article({slug:"p0135",code:"P0135",title:"P0135 Code Honda Pilot: Bank 1 Sensor 1 Heater Circuit Diagnosis",description:"Diagnose Pilot P0135 by locating Bank 1 Sensor 1 and testing heater power, PCM control, current, resistance and exhaust-side harness damage.",definition:"Oxygen Sensor Heater Circuit Malfunction (Bank 1, Sensor 1)",severity:"Service soon",driveAdvice:"A heater-only code usually allows brief driving, but stop for flashing misfire, repeatedly blown fuses, melted wiring or severe exhaust damage. Let both exhaust banks cool before working around shields and connectors.",quickAnswer:"P0135 means the PCM did not see expected heater-circuit behavior from Bank 1 Sensor 1, the upstream feedback sensor on the J35's Bank 1 exhaust. It does not mean Bank 1 catalyst or downstream sensor. First identify Bank 1 from the exact model-year diagram, then verify the connector, loaded fused supply, shared feed, heater resistance/current and PCM-controlled circuit. Compare Bank 2 when the hardware is equivalent. If P0155 or other heater codes accompany it, a shared power source is more plausible than simultaneous sensor failures.",symptoms:[{key:"cold",label:"MIL returns after cold start",response:"Capture command/current before exhaust heat changes resistance."},{key:"both",label:"P0135 and P0155",response:"Test shared heater supply and grounds first."},{key:"fuse",label:"Fuse blows repeatedly",response:"Locate the short; do not increase fuse rating."},{key:"repair",label:"Started after exhaust work",response:"Inspect crossed connectors, routing and terminal damage."}],causes:[{cause:"Open Bank 1 upstream heater",evidence:"Correct element fails resistance/current test",firstTest:"Cold element test"},{cause:"Missing fused battery feed",evidence:"Voltage absent/collapses under load",firstTest:"Fuse/relay/feed voltage drop"},{cause:"PCM-control wire open/short",evidence:"Command present but current incorrect",firstTest:"Loaded circuit test"},{cause:"Heat/chafe/corrosion damage",evidence:"Visual or heat/vibration dropout",firstTest:"Harness/terminal inspection"},{cause:"Wrong sensor/connector assignment",evidence:"Fault after service and part/routing mismatch",firstTest:"VIN part and bank verification"}],freezeFrame:["Battery voltage, ECT and time since start","Bank 1 heater command/current","P0155 and shared-circuit codes","Fuse state","Recent exhaust repairs","VIN, bank diagram and sensor part"],steps:[{title:"Identify Bank 1 Sensor 1",detail:"Use the specific J35 diagram; do not guess front/rear."},{title:"Check all heater codes",detail:"Multiple banks change the first test to shared power."},{title:"Inspect cold harness",detail:"Look for melted, stretched or crossed connectors."},{title:"Test supply under load",detail:"Open-circuit voltage can hide resistance."},{title:"Test element and PCM control",detail:"Use exact pinout/specification."},{title:"Verify cold start",detail:"Confirm heater current and no pending P0135."}],dontReplace:"Do not replace the sensor without power/control tests or use a Bank 2/downstream part because it fits. Never upsize a heater fuse; a short near hot exhaust can damage the harness.",yearNotes:["Bank 1 location must come from the exact J35 model-year diagram.","Port- and direct-injected generations can use different A/F sensors and heater values.","P0155 is the corresponding Bank 2 Sensor 1 heater code on many strategies.","VIN/emissions calibration controls the correct sensor part."],faqs:[{question:"Which sensor is P0135?",answer:"Bank 1's upstream/pre-catalyst feedback sensor heater."},{question:"Does it prove the sensor signal is bad?",answer:"No. The code concerns the heater circuit."},{question:"Can I drive?",answer:"Usually briefly if operation and wiring are safe."},{question:"Why check P0155?",answer:"Both upstream heaters may share power."},{question:"Can a fuse cause it?",answer:"Yes, but find why it opened."},{question:"Can I test resistance?",answer:"Yes, using Honda's exact pins/specification."},{question:"Will a universal sensor work?",answer:"It risks incorrect heater and signal characteristics."},{question:"What confirms repair?",answer:"Normal cold-start heater current and no pending P0135."}],deepDive:[{heading:"Bank identification is the first electrical test",paragraphs:["Testing the wrong upstream connector can produce convincing but irrelevant measurements.","Trace cylinder bank, exhaust and connector using the service diagram."]},{heading:"Compare equivalent banks",paragraphs:["When sensors share part and operating conditions, Bank 2 can provide a useful current/response reference.","Do not assume they are electrically identical without checking the diagram."]},{heading:"Loaded testing reveals terminal resistance",paragraphs:["A weak terminal may show battery voltage with the heater disconnected and collapse under current.","Voltage drop and measured current expose capacity."]}],sources:[sx,manuals]}),

article({slug:"p0455",code:"P0455",title:"P0455 Code Honda Pilot: Large EVAP Leak by Filler Generation",description:"Diagnose Pilot P0455 with cap or capless-filler checks, purge/vent sealing, FTP data and safe smoke testing, including 2012–2013 and 2016 Honda branches.",definition:"EVAP System Large Leak Detected",severity:"Service soon",driveAdvice:"Brief driving is generally acceptable without fuel odor or visible leakage. Park outdoors and stop for gasoline wetness, strong vapor odor, tank damage or refueling spit-back. Do not introduce uncontrolled shop air.",quickAnswer:"P0455 means the EVAP monitor could not create or hold expected pressure; it does not locate the leak. Pilot has two important generation branches. Bulletin 14-010 covers all 2012 Pilots and specified early-production 2013 2WD/4WD VIN ranges for a conventional cap-gasket friction condition. A Honda Tech Line article for 2016 Pilot says that when leakage is verified at the capless filler neck, service the mis-fuel inhibit device and main-flap unit rather than replacing the entire fill pipe. Other causes—purge/vent valves, hoses, canister, tank seals and FTP bias—still require testing.",symptoms:[{key:"cap",label:"2012/early 2013 with sticky cap",response:"Check VIN and 14-010 cap inspection."},{key:"capless",label:"2016 leak verified at filler",response:"Use serviceable flap components per ATS 170206."},{key:"start",label:"Hard start after refueling",response:"Test purge-valve closed-state sealing."},{key:"odor",label:"Strong fuel odor",response:"Stop and inspect for liquid leakage."}],causes:[{cause:"Loose/damaged/sticky conventional cap",evidence:"Found condition or 14-010 test",firstTest:"Cap/filler inspection"},{cause:"2016 capless main-flap/mis-fuel device leak",evidence:"Leak localized at filler",firstTest:"Tech Line component procedure"},{cause:"Purge valve stuck open",evidence:"Vacuum passes commanded closed",firstTest:"Closed-state sealing"},{cause:"Vent/hose/canister leak",evidence:"Cannot seal; smoke localizes",firstTest:"Command and smoke test"},{cause:"Tank/pump seal or FTP sensor fault",evidence:"Recent service or implausible data",firstTest:"Sectional leak/signal test"}],freezeFrame:["Fuel level and soak/ambient temperature","FTP sensor data","Purge/vent commands","P0456/P0441/electrical companions","Filler/cap found condition","VIN, year and recent tank work"],steps:[{title:"Identify filler generation",detail:"Conventional-cap and capless repairs are not interchangeable."},{title:"Preserve found condition",detail:"Record cap/flap behavior before manipulating it."},{title:"Apply exact Honda branch",detail:"Check 2012–2013 VIN range or verify 2016 filler leak location."},{title:"Test valve sealing",detail:"A click is not a sealing test."},{title:"Use regulated smoke and validate FTP",detail:"Section system safely and compare sensor response."},{title:"Complete monitor",detail:"Meet fuel/soak conditions and check pending code."}],dontReplace:"Do not replace the complete 2016 fill pipe when Honda provides serviceable flap components for a confirmed filler leak. Do not apply that branch to other years, or assume every 2012–2013 code is the cap without testing.",yearNotes:["14-010 covers all 2012 Pilot and published early 2013 2WD/4WD VIN ranges.","ATS 170206 names 2016 Pilot capless filler-neck leaks.","2003–2004 P1456/P1457 systems use different diagnostic regions.","Later capless assemblies and EVAP calibrations require year-correct service information."],faqs:[{question:"Is P0455 always a gas cap?",answer:"No. Valves, hoses, canister, tank seals, sensing and capless flaps can cause it."},{question:"Does 14-010 cover every 2013 Pilot?",answer:"No. It lists early-production VIN ranges."},{question:"Should a 2016 get a complete fill pipe?",answer:"Not for the verified condition in ATS 170206; serviceable flap parts are specified."},{question:"Can I drive?",answer:"Usually briefly without odor or liquid fuel."},{question:"Can purge leakage cause hard starts?",answer:"Yes, especially after refueling."},{question:"Can I use shop air?",answer:"Not unregulated; EVAP systems need controlled low pressure."},{question:"Why won't readiness complete?",answer:"Fuel level, soak and temperature gate the monitor."},{question:"What confirms repair?",answer:"Correct valve/FTP behavior and a completed EVAP monitor."}],deepDive:[{heading:"Pilot filler hardware changed the first inspection",paragraphs:["A conventional cap can bind on its gasket; a capless filler seals through internal flap components.","Applying one generation's repair to another wastes parts and may damage the assembly."]},{heading:"Leak location must be proven",paragraphs:["The 2016 article begins with an EVAP leak verified at the filler neck.","It is not a directive to replace flap parts for every P0455."]},{heading:"An open valve resembles a hole",paragraphs:["Purge and vent paths must close during portions of the monitor.","Prove mechanical sealing before condemning the tank or canister."]}],sources:[capEvap,filler2016,sx]}),

article({slug:"p0128",code:"P0128",title:"P0128 Code Honda Pilot: V6 Thermostat and Warm-Up Diagnosis",description:"Diagnose Pilot P0128 with cold ECT/IAT comparison, a graphed J35 warm-up curve, fan operation and correct thermostat/bleeding checks.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"P0128 usually indicates slow warm-up, but stop for overheating, steam, coolant loss, a temperature warning or heater output suddenly going cold. With correct cold coolant level and stable temperature, a short diagnostic drive is usually reasonable.",quickAnswer:"P0128 means J35 coolant temperature remained below the PCM's modeled regulation range after sufficient operating time/load. A thermostat stuck open is common, but begin after overnight soak: ECT and IAT should be close to ambient. Graph ECT, time, road speed, engine load, radiator-fan command and heater output. Low coolant, trapped air after service, a cold-biased ECT sensor, unwanted fan operation or an incorrect thermostat can duplicate the code. Towing load, rear HVAC demand and ambient weather affect the trace, but do not replace the need for sensor plausibility and Honda's model-year threshold.",symptoms:[{key:"heat",label:"Cabin heat is slow",response:"Check coolant cold and graph warm-up."},{key:"road",label:"ECT falls on highway",response:"Thermostat leakage becomes likely; verify with data."},{key:"gauge",label:"Gauge appears normal",response:"Use scan ECT because the display is damped."},{key:"hot",label:"Temperature climbs/coolant escapes",response:"Stop and diagnose overheating, not P0128."}],causes:[{cause:"Thermostat stuck open/incorrect",evidence:"Slow rise and highway drop",firstTest:"Cold-start warm-up graph"},{cause:"ECT sensor/circuit cold bias",evidence:"Cold ECT differs from IAT/ambient",firstTest:"Cold-soak plausibility"},{cause:"Low coolant/trapped air",evidence:"Low level, recent service, unstable heater",firstTest:"Leak check and proper bleed"},{cause:"Fans operating without valid request",evidence:"Cold fans with A/C off/no command",firstTest:"Command versus actual"},{cause:"Invalid load/temperature input",evidence:"Companion code or implausible data",firstTest:"Resolve prerequisite fault"}],freezeFrame:["ECT/IAT/measured ambient","Time, rpm, load and speed","Fan command/A-C request","Coolant level/recent service","Front/rear heater demand","Companion voltage/load codes"],steps:[{title:"Start after a true cold soak",detail:"A thermostat cannot cause pre-start sensor disagreement."},{title:"Inspect cooling system cold",detail:"Never open a hot pressurized cap."},{title:"Graph entire warm-up",detail:"Capture rise, regulation and road-speed drop."},{title:"Observe fan request/action",detail:"Account for A/C and HVAC commands."},{title:"Verify thermostat and bleed",detail:"Use exact J35 part, orientation and air-removal procedure."},{title:"Repeat comparable drive",detail:"Confirm stable regulation and no pending P0128."}],dontReplace:"Do not replace the thermostat before checking cold sensor plausibility. Wrong parts and trapped air create repeat failures; low coolant can become an overheating emergency. The dash gauge is not a calibrated test instrument.",yearNotes:["J35 generations use different housing access, thermostat specifications and bleeding procedures.","Rear HVAC/heater demand changes heat removal during testing.","Cold ambient changes warm-up time, but the PCM has enable logic.","Use exact scan ECT and Honda procedure rather than gauge position."],faqs:[{question:"Is P0128 always the thermostat?",answer:"No. Sensor bias, low coolant, air and fan faults can mimic it."},{question:"Can I drive?",answer:"Usually briefly if coolant is full and temperature stable."},{question:"Why does the gauge look normal?",answer:"It is damped across a broad range."},{question:"Can winter cause it?",answer:"Weather affects warm-up, but repeated monitor failure needs diagnosis."},{question:"Can fuel economy fall?",answer:"Yes, prolonged warm-up affects enrichment."},{question:"Can I open the cap hot?",answer:"No; pressurized coolant can burn."},{question:"Why compare ECT and IAT?",answer:"Both should approach ambient during a long soak."},{question:"What confirms repair?",answer:"Plausible cold values and stable regulation without pending P0128."}],deepDive:[{heading:"Cold-soak comparison precedes parts",paragraphs:["Before start, coolant and intake sensors have shared the same ambient environment.","A large mismatch indicates sensing/circuit bias regardless of thermostat position."]},{heading:"Highway airflow tests regulation",paragraphs:["A leaking-open thermostat may allow ECT to drop as radiator airflow increases.","Graph speed and load with temperature rather than relying on memory."]},{heading:"HVAC load changes the curve",paragraphs:["The Pilot can remove significant heat through front/rear cabin heaters.","Record HVAC state so a before/after test is comparable."]}],sources:[sx,manuals]}),

article({slug:"p0301",code:"P0301",title:"P0301 Code Honda Pilot: Cylinder 1 Misfire and Bulletin Branches",description:"Diagnose Pilot P0301 with correct J35 cylinder location, plug/coil/injector/compression tests and exact 2009–2013 Honda applicability.",definition:"Cylinder 1 Misfire Detected",severity:"Stop soon",driveAdvice:"Stop sustained driving for a flashing MIL or severe shaking; raw fuel can overheat the bank's catalyst. With a steady lamp and mild intermittent symptom, restrict movement to diagnosis and avoid towing or hard acceleration.",quickAnswer:"P0301 means the PCM attributed excessive misfire to cylinder 1, not that coil 1 failed. Locate cylinder 1 from the exact J35 diagram, save cold/load counters and keep plugs in order. One controlled coil swap can prove ignition; if the count stays, test injector delivery/circuit and compression/leak-down. For specified 2009–2013 Pilots, bulletin 13-082 provides a plug-fouling/software/piston-ring sequence for P0301–P0304. A separate narrow 13-055 branch applies to selected 2013 VINs with cold ECT below 30°F and rocker-arm oil pressure above 92 psi. Neither repair follows from P0301 alone.",symptoms:[{key:"flash",label:"MIL flashes",response:"Stop loading and protect the catalyst."},{key:"oil",label:"2009–2013 plug 1 oil-fouled",response:"Check 13-082 VIN/status and procedure sequence."},{key:"cold",label:"Selected 2013 very-cold start",response:"Evaluate 13-055 thresholds and companion codes."},{key:"swap",label:"Misfire follows coil",response:"Inspect boot/connector and replace proven fault."}],causes:[{cause:"Plug 1 fouled/worn/cracked",evidence:"Abnormal deposit/gap/damage",firstTest:"Labelled plug comparison"},{cause:"Coil/boot/connector fault",evidence:"Misfire follows controlled swap or circuit fails",firstTest:"One swap and loaded test"},{cause:"Injector restriction/leak/circuit",evidence:"Count stays and contribution differs",firstTest:"Injector balance/leak/command"},{cause:"Compression/valve/timing fault",evidence:"Low relative/measured compression",firstTest:"Compression then leak-down"},{cause:"13-082 or 13-055 matched condition",evidence:"Every year/VIN/code/plug or temperature/pressure gate matches",firstTest:"Exact bulletin workflow"}],freezeFrame:["Cylinder 1/all-cylinder counts","RPM, load, ECT and speed","Bank corrections/fuel pressure","Plug 1 versus neighbors","Rocker-arm pressure for cold 2013 branch","VIN/software/warranty status"],steps:[{title:"Identify cylinder 1 correctly",detail:"Use exact J35 layout before touching coils/injectors."},{title:"Preserve cold/load condition",detail:"Capture before warm-up changes it."},{title:"Inspect plug 1 in context",detail:"Photograph and compare all relevant plugs."},{title:"Make one coil swap",detail:"Observe whether the counter follows."},{title:"Test injector and sealing",detail:"If it stays, prove fuel and compression."},{title:"Check bulletin gates",detail:"Do not skip VIN, plug, temperature, pressure or prior-repair conditions."},{title:"Verify original conditions",detail:"Confirm no pending P0301 without provoking flashing MIL."}],dontReplace:"Do not replace all coils or promise piston-ring/relief-spring repair from P0301. Honda's programs require precise evidence and current VIN status. A new plug can hide injector or mechanical failure temporarily.",yearNotes:["13-082 covers specified 2009–2013 P0301–P0304 plug-fouling/ring cases.","13-055 is a narrow selected-2013 VIN/cold-pressure branch.","Later direct-injected Pilots require injector and high-pressure evaluation.","Correct cylinder and bank identification protects against testing the wrong catalyst/injector."],faqs:[{question:"Is P0301 always a coil?",answer:"No. Plug, injector, circuit, compression and valve/timing faults can cause it."},{question:"Can I drive?",answer:"Not with flashing MIL or severe shaking."},{question:"Does every 2009–2013 Pilot need rings?",answer:"No. Bulletin diagnosis and eligibility determine that."},{question:"Can I swap coils?",answer:"Yes, carefully, while monitoring whether the count follows."},{question:"What if it stays on cylinder 1?",answer:"Test injector delivery/circuit and compression."},{question:"Does every cold 2013 need a relief spring?",answer:"No. VIN, ECT, pressure and code thresholds apply."},{question:"Should I clear first?",answer:"No. Preserve freeze data and counts."},{question:"What confirms repair?",answer:"No cylinder 1 count under the original condition."}],deepDive:[{heading:"One cylinder still has several systems",paragraphs:["A cylinder code localizes combustion disturbance, not whether spark, fuel or sealing caused it.","Follow evidence from plug, controlled swap, injector and compression in that order."]},{heading:"Bulletin 13-082 is sequential",paragraphs:["Software, plug condition, repeat occurrence and model year affect its repair path.","Skipping directly to ring replacement misrepresents Honda's diagnostic requirements."]},{heading:"The cold 2013 branch uses hard thresholds",paragraphs:["13-055 requires listed VINs, ECT below 30°F and rocker-arm oil pressure above 92 psi.","A cold morning or P0301 alone is insufficient."]}],sources:[rings,coldOil,sx]}),
];
